import React from 'react';
import './App.css';

export function Stages({ stagePass }) {
  const stages = [
    { id: 8, value: '1.000.000' },
    { id: 7, value: '500.000' },
    { id: 6, value: '250.000' },
    { id: 5, value: '125.000' },
    { id: 4, value: '64.000' },
    { id: 3, value: '32.000' },
    { id: 2, value: '16.000' },
    { id: 1, value: '8.000' },
    { id: 0, value: '1.000' },
  ];

  return (
    <div className="game_stages">
      {stages.map((stage) => (
        <div
          key={stage.id}
          className={`stage ${stage.id === stagePass ? 'current' : ''}`}
          id={`stage_${stage.id}`}
        >
          {stage.value}
        </div>
      ))}
      <div className="total_take">Total: 16.000$</div>
    </div>
  );
}
